# bash completion for nightshift — generated by `nightshift completion bash`
_nightshift() {
    local cur="${COMP_WORDS[COMP_CWORD]}" reply
    reply=$(__NIGHTSHIFT_BIN__ __complete "${COMP_WORDS[@]:1:COMP_CWORD-1}" "$cur" 2>/dev/null)
    COMPREPLY=()
    if [[ $reply == __dirs__ ]]; then
        compopt -o filenames 2>/dev/null
        mapfile -t COMPREPLY < <(compgen -d -- "$cur")
    elif [[ -n $reply ]]; then
        mapfile -t COMPREPLY <<<"$reply"
    fi
}
complete -F _nightshift nightshift
